69	  /// Return the device presented to the user as device \p DeviceNo if it is
70	  /// initialized and ready. Otherwise return an error explaining the problem.
71	  llvm::Expected<DeviceTy &> getDevice(uint32_t DeviceNo);
72	
73	  /// Iterate over all initialized and ready devices registered with this
74	  /// plugin.
75	  auto devices(ExclusiveDevicesAccessorTy &DevicesAccessor) {
76	    return llvm::make_pointee_range(*DevicesAccessor);
77	  }
78	
79	  /// Iterate over all device images registered with this plugin.
80	  auto deviceImages() { return llvm::make_pointee_range(DeviceImages); }
81	
82	  /// Translation table retrieved from the binary
83	  HostEntriesBeginToTransTableTy HostEntriesBeginToTransTable;
84	  std::mutex TrlTblMtx; ///< For Translation Table
85	  /// Host offload entries in order of image registration
86	  llvm::SmallVector<llvm::offloading::EntryTy *>
87	      HostEntriesBeginRegistrationOrder;
88	
89	  /// Map from ptrs on the host to an entry in the Translation Table
90	  HostPtrToTableMapTy HostPtrToTableMap;
91	  std::mutex TblMapMtx; ///< For HostPtrToTableMap
92	
93	  /// Table of cached implicit interop objects
94	  InteropTblTy InteropTbl;
95	
96	  // Work around for plugins that call dlopen on shared libraries that call
97	  // tgt_register_lib during their initialisation. Stash the pointers in a
98	  // vector until the plugins are all initialised and then register them.
99	  bool delayRegisterLib(__tgt_bin_desc *Desc) {
100	    if (RTLsLoaded)
101	      return false;
102	    DelayedBinDesc.push_back(Desc);
103	    return true;
104	  }
