114	  /// Return the number of usable devices.
115	  int getNumDevices() { return getExclusiveDevicesAccessor()->size(); }
116	
117	  /// Return an exclusive handle to access the devices container.
118	  ExclusiveDevicesAccessorTy getExclusiveDevicesAccessor() {
