137	  /// Return the user provided requirements.
138	  int64_t getRequirements() const { return Requirements.getRequirements(); }
139	
140	  /// Add \p Flags to the user provided requirements.
141	  void addRequirements(int64_t Flags) { Requirements.addRequirements(Flags); }
142	
143	  /// Returns the number of plugins that are active.
144	  int getNumActivePlugins() const {
145	    int count = 0;
146	    for (auto &R : plugins())
147	      if (R.is_initialized())
148	        ++count;
149	
150	    return count;
151	  }
152	
153	private:
154	  bool RTLsLoaded = false;
155	  llvm::SmallVector<__tgt_bin_desc *> DelayedBinDesc;
156	
157	  // List of all plugins, in use or not.
158	  llvm::SmallVector<std::unique_ptr<GenericPluginTy>> Plugins;
159	
160	  // Mapping of plugins to the OpenMP device identifier.
161	  llvm::DenseMap<std::pair<const GenericPluginTy *, int32_t>, int32_t>
162	      DeviceIds;
163	
164	  // Set of all device images currently in use.
165	  llvm::DenseSet<const __tgt_device_image *> UsedImages;
166	
167	  /// Executable images and information extracted from the input images passed
168	  /// to the runtime.
169	  llvm::SmallVector<std::unique_ptr<DeviceImageTy>> DeviceImages;
170	
171	  /// The user provided requirements.
172	  RequirementCollection Requirements;
173	
174	  std::mutex RTLsMtx; ///< For RTLs
175	
