177	  ProtectedObj<DeviceContainerTy> Devices;
178	
179	  /// References to upgraded legacy offloading entries.
180	  std::list<llvm::SmallVector<llvm::offloading::EntryTy, 0>> LegacyEntries;
181	  std::list<llvm::SmallVector<__tgt_device_image, 0>> LegacyImages;
182	  llvm::DenseMap<__tgt_bin_desc *, __tgt_bin_desc> UpgradedDescriptors;
183	  __tgt_bin_desc *upgradeLegacyEntries(__tgt_bin_desc *Desc);
184	};
