1	//===-- PluginManager.cpp - Plugin loading and communication API ---------===//
2	//
3	// Part of the LLVM Project, under the Apache License v2.0 with LLVM Exceptions.
4	// See https://llvm.org/LICENSE.txt for license information.
5	// SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
6	//
7	//===----------------------------------------------------------------------===//
8	//
9	// Functionality for handling plugins.
10	//
11	//===----------------------------------------------------------------------===//
12	
13	#include "PluginManager.h"
14	#include "OffloadPolicy.h"
15	#include "Shared/Debug.h"
16	#include "Shared/Profile.h"
17	#include "device.h"
18	
19	#include "llvm/Support/Error.h"
20	#include "llvm/Support/ErrorHandling.h"
21	#include <memory>
22	
23	using namespace llvm;
24	using namespace llvm::sys;
25	using namespace llvm::omp::target::debug;
26	
27	PluginManager *PM = nullptr;
28	
29	// Every plugin exports this method to create an instance of the plugin type.
30	#define PLUGIN_TARGET(Name) extern "C" GenericPluginTy *createPlugin_##Name();
31	#include "Shared/Targets.def"
32	
33	void PluginManager::init() {
34	  TIMESCOPE();
35	  if (OffloadPolicy::isOffloadDisabled()) {
36	    ODBG(ODT_Init) << "Offload is disabled. Skipping plugin initialization";
37	    return;
38	  }
39	
40	  ODBG(ODT_Init) << "Loading RTLs";
41	
42	  // Attempt to create an instance of each supported plugin.
43	#define PLUGIN_TARGET(Name)                                                    \
44	  do {                                                                         \
45	    Plugins.emplace_back(                                                      \
46	        std::unique_ptr<GenericPluginTy>(createPlugin_##Name()));              \
47	  } while (false);
48	#include "Shared/Targets.def"
49	
50	  ODBG(ODT_Init) << "RTLs loaded!";
51	}
52	
53	void PluginManager::deinit() {
54	  TIMESCOPE();
55	  ODBG(ODT_Deinit) << "Unloading RTLs...";
56	
57	  for (auto &Plugin : Plugins) {
58	    if (!Plugin->is_initialized())
59	      continue;
60	
61	    if (auto Err = Plugin->deinit()) {
62	      std::string InfoMsg = toString(std::move(Err));
63	      ODBG(ODT_Deinit) << "Failed to deinit plugin: " << InfoMsg;
64	    }
65	    Plugin.release();
66	  }
67	
68	  ODBG(ODT_Deinit) << "RTLs unloaded!";
69	}
70	
71	bool PluginManager::initializePlugin(GenericPluginTy &Plugin) {
72	  if (Plugin.is_initialized())
73	    return true;
74	
75	  if (auto Err = Plugin.init()) {
76	    std::string InfoMsg = toString(std::move(Err));
77	    ODBG(ODT_Init) << "Failed to init plugin: " << InfoMsg;
78	    return false;
79	  }
80	
81	  ODBG(ODT_Init) << "Registered plugin " << Plugin.getName() << " with "
82	                 << Plugin.number_of_devices() << " visible device(s)";
83	
84	  return true;
85	}
86	
87	bool PluginManager::initializeDevice(GenericPluginTy &Plugin,
88	                                     int32_t DeviceId) {
89	  if (Plugin.is_device_initialized(DeviceId)) {
90	    auto ExclusiveDevicesAccessor = getExclusiveDevicesAccessor();
91	    (*ExclusiveDevicesAccessor)[PM->DeviceIds[std::make_pair(&Plugin,
92	                                                             DeviceId)]]
93	        ->setHasPendingImages(true);
94	    return true;
95	  }
96	
97	  // Initialize the device information for the RTL we are about to use.
98	  auto ExclusiveDevicesAccessor = getExclusiveDevicesAccessor();
99	
100	  int32_t UserId = ExclusiveDevicesAccessor->size();
101	
102	  // Set the device identifier offset in the plugin.
103	#ifdef OMPT_SUPPORT
104	  Plugin.set_device_identifier(UserId, DeviceId);
105	#endif
106	
107	  auto Device = std::make_unique<DeviceTy>(&Plugin, UserId, DeviceId);
108	  if (auto Err = Device->init()) {
109	    std::string InfoMsg = toString(std::move(Err));
110	    ODBG(ODT_Init) << "Failed to init device " << DeviceId << ": " << InfoMsg;
111	    return false;
112	  }
113	
114	  ExclusiveDevicesAccessor->push_back(std::move(Device));
115	
116	  // We need to map between the plugin's device identifier and the one
117	  // that OpenMP will use.
118	  PM->DeviceIds[std::make_pair(&Plugin, DeviceId)] = UserId;
119	
120	  return true;
121	}
122	
123	void PluginManager::initializeAllDevices() {
124	  for (auto &Plugin : plugins()) {
125	    if (!initializePlugin(Plugin))
126	      continue;
127	
128	    for (int32_t DeviceId = 0; DeviceId < Plugin.number_of_devices();
129	         ++DeviceId) {
130	      initializeDevice(Plugin, DeviceId);
131	    }
132	  }
133	  // After all plugins are initialized, register atExit cleanup handlers
134	  std::atexit([]() {
135	    // Interop cleanup should be done before the plugins are deinitialized as
136	    // the backend libraries may be already unloaded.
137	    if (PM)
138	      PM->InteropTbl.clear();
139	  });
140	}
141	
142	// Returns a pointer to the binary descriptor, upgrading from a legacy format if
143	// necessary.
144	__tgt_bin_desc *PluginManager::upgradeLegacyEntries(__tgt_bin_desc *Desc) {
145	  struct LegacyEntryTy {
146	    void *Address;
147	    char *SymbolName;
148	    size_t Size;
149	    int32_t Flags;
150	    int32_t Data;
151	  };
152	
153	  if (UpgradedDescriptors.contains(Desc))
154	    return &UpgradedDescriptors[Desc];
155	
156	  if (Desc->HostEntriesBegin == Desc->HostEntriesEnd ||
157	      Desc->HostEntriesBegin->Reserved == 0)
158	    return Desc;
159	
160	  // The new format mandates that each entry starts with eight bytes of zeroes.
161	  // This allows us to detect the old format as this is a null pointer.
162	  llvm::SmallVector<llvm::offloading::EntryTy, 0> &NewEntries =
163	      LegacyEntries.emplace_back();
164	  for (LegacyEntryTy &Entry : llvm::make_range(
165	           reinterpret_cast<LegacyEntryTy *>(Desc->HostEntriesBegin),
166	           reinterpret_cast<LegacyEntryTy *>(Desc->HostEntriesEnd))) {
167	    llvm::offloading::EntryTy &NewEntry = NewEntries.emplace_back();
168	
169	    NewEntry.Address = Entry.Address;
170	    NewEntry.Flags = Entry.Flags;
171	    NewEntry.Data = Entry.Data;
172	    NewEntry.Size = Entry.Size;
173	    NewEntry.SymbolName = Entry.SymbolName;
174	    NewEntry.Kind = object::OffloadKind::OFK_OpenMP;
175	  }
176	
177	  // Create a new image struct so we can update the entries list.
178	  llvm::SmallVector<__tgt_device_image, 0> &NewImages =
179	      LegacyImages.emplace_back();
180	  for (int32_t Image = 0; Image < Desc->NumDeviceImages; ++Image)
181	    NewImages.emplace_back(
182	        __tgt_device_image{Desc->DeviceImages[Image].ImageStart,
183	                           Desc->DeviceImages[Image].ImageEnd,
184	                           NewEntries.begin(), NewEntries.end()});
185	
186	  // Create the new binary descriptor containing the newly created memory.
187	  __tgt_bin_desc &NewDesc = UpgradedDescriptors[Desc];
188	  NewDesc.DeviceImages = NewImages.begin();
189	  NewDesc.NumDeviceImages = Desc->NumDeviceImages;
190	  NewDesc.HostEntriesBegin = NewEntries.begin();
191	  NewDesc.HostEntriesEnd = NewEntries.end();
192	
193	  return &NewDesc;
194	}
195	
196	void PluginManager::registerLib(__tgt_bin_desc *Desc) {
197	  PM->RTLsMtx.lock();
198	
199	  // Upgrade the entries from the legacy implementation if necessary.
200	  Desc = upgradeLegacyEntries(Desc);
201	
202	  // Add in all the OpenMP requirements associated with this binary.
203	  for (llvm::offloading::EntryTy &Entry :
204	       llvm::make_range(Desc->HostEntriesBegin, Desc->HostEntriesEnd))
205	    if (Entry.Kind == object::OffloadKind::OFK_OpenMP &&
206	        Entry.Flags == OMP_REGISTER_REQUIRES)
207	      PM->addRequirements(Entry.Data);
208	
209	  // Extract the executable image and extra information if available.
210	  for (int32_t i = 0; i < Desc->NumDeviceImages; ++i)
211	    PM->addDeviceImage(*Desc, Desc->DeviceImages[i]);
212	
213	  // Register the images with the RTLs that understand them, if any.
214	  llvm::DenseMap<GenericPluginTy *, llvm::DenseSet<int32_t>> UsedDevices;
215	  for (int32_t i = 0; i < Desc->NumDeviceImages; ++i) {
216	    // Obtain the image and information that was previously extracted.
217	    __tgt_device_image *Img = &Desc->DeviceImages[i];
218	
219	    GenericPluginTy *FoundRTL = nullptr;
220	
221	    // Scan the RTLs that have associated images until we find one that supports
222	    // the current image.
223	    for (auto &R : plugins()) {
224	      StringRef Buffer(reinterpret_cast<const char *>(Img->ImageStart),
225	                       utils::getPtrDiff(Img->ImageEnd, Img->ImageStart));
226	
227	      if (!R.isPluginCompatible(Buffer))
228	        continue;
229	
230	      if (!initializePlugin(R))
231	        continue;
232	
233	      if (!R.number_of_devices()) {
234	        ODBG(ODT_Init) << "Skipping plugin " << R.getName()
235	                       << " with no visible devices";
236	        continue;
237	      }
238	
239	      for (int32_t DeviceId = 0; DeviceId < R.number_of_devices(); ++DeviceId) {
240	        // We only want a single matching image to be registered for each binary
241	        // descriptor. This prevents multiple of the same image from being
242	        // registered for the same device in the case that they are mutually
243	        // compatible, such as sm_80 and sm_89.
244	        if (UsedDevices[&R].contains(DeviceId)) {
245	          ODBG(ODT_Init) << "Image " << Img->ImageStart
246	                         << " is a duplicate, not loaded on RTL " << R.getName()
247	                         << " device " << DeviceId;
248	          continue;
249	        }
250	
251	        if (!R.isDeviceCompatible(DeviceId, Buffer))
252	          continue;
253	
254	        ODBG(ODT_Init) << "Image " << Img->ImageStart
255	                       << " is compatible with RTL " << R.getName()
256	                       << " device " << DeviceId;
257	
258	        if (!initializeDevice(R, DeviceId))
259	          continue;
260	
261	        // Initialize (if necessary) translation table for this library.
262	        PM->TrlTblMtx.lock();
263	        if (!PM->HostEntriesBeginToTransTable.count(Desc->HostEntriesBegin)) {
264	          PM->HostEntriesBeginRegistrationOrder.push_back(
265	              Desc->HostEntriesBegin);
266	          TranslationTable &TT =
267	              (PM->HostEntriesBeginToTransTable)[Desc->HostEntriesBegin];
268	          TT.HostTable.EntriesBegin = Desc->HostEntriesBegin;
269	          TT.HostTable.EntriesEnd = Desc->HostEntriesEnd;
270	        }
271	
272	        // Retrieve translation table for this library.
273	        TranslationTable &TT =
274	            (PM->HostEntriesBeginToTransTable)[Desc->HostEntriesBegin];
275	
276	        ODBG(ODT_Init) << "Registering image " << Img->ImageStart
277	                       << " with RTL " << R.getName();
278	
279	        auto UserId = PM->DeviceIds[std::make_pair(&R, DeviceId)];
280	        if (TT.TargetsTable.size() < static_cast<size_t>(UserId + 1)) {
281	          TT.DeviceTables.resize(UserId + 1, {});
282	          TT.TargetsImages.resize(UserId + 1, nullptr);
283	          TT.TargetsEntries.resize(UserId + 1, {});
284	          TT.TargetsTable.resize(UserId + 1, nullptr);
285	        }
286	
287	        // Register the image for this target type and invalidate the table.
288	        TT.TargetsImages[UserId] = Img;
289	        TT.TargetsTable[UserId] = nullptr;
290	
291	        UsedDevices[&R].insert(DeviceId);
292	        PM->UsedImages.insert(Img);
293	        FoundRTL = &R;
294	
295	        PM->TrlTblMtx.unlock();
296	      }
297	    }
298	    if (!FoundRTL)
299	      ODBG(ODT_Init) << "No RTL found for image " << Img->ImageStart << "!";
300	  }
301	  PM->RTLsMtx.unlock();
302	
303	  bool UseAutoZeroCopy = false;
304	
305	  auto ExclusiveDevicesAccessor = getExclusiveDevicesAccessor();
306	  // APUs are homogeneous set of GPUs. Check the first device for
307	  // configuring Auto Zero-Copy.
308	  if (ExclusiveDevicesAccessor->size() > 0) {
309	    auto &Device = *(*ExclusiveDevicesAccessor)[0];
310	    UseAutoZeroCopy = Device.useAutoZeroCopy();
311	  }
312	
313	  if (UseAutoZeroCopy)
314	    addRequirements(OMPX_REQ_AUTO_ZERO_COPY);
315	
316	  ODBG(ODT_Init) << "Done registering entries!";
317	}
318	
319	// Temporary forward declaration, old style CTor/DTor handling is going away.
320	int target(ident_t *Loc, DeviceTy &Device, void *HostPtr,
321	           KernelArgsTy &KernelArgs, AsyncInfoTy &AsyncInfo);
322	
323	void PluginManager::unregisterLib(__tgt_bin_desc *Desc) {
324	  ODBG(ODT_Deinit) << "Unloading target library!";
325	
326	  Desc = upgradeLegacyEntries(Desc);
327	
328	  PM->RTLsMtx.lock();
329	  // Find which RTL understands each image, if any.
330	  for (DeviceImageTy &DI : PM->deviceImages()) {
331	    // Obtain the image and information that was previously extracted.
332	    __tgt_device_image *Img = &DI.getExecutableImage();
333	
334	    GenericPluginTy *FoundRTL = NULL;
335	
336	    // Scan the RTLs that have associated images until we find one that supports
337	    // the current image. We only need to scan RTLs that are already being used.
338	    for (auto &R : plugins()) {
339	      if (R.is_initialized())
340	        continue;
341	
342	      // Ensure that we do not use any unused images associated with this RTL.
343	      if (!UsedImages.contains(Img))
344	        continue;
345	
346	      FoundRTL = &R;
347	
348	      ODBG(ODT_Deinit) << "Unregistered image " << Img->ImageStart
349	                       << " from RTL";
350	
351	      break;
352	    }
353	
354	    // if no RTL was found proceed to unregister the next image
355	    if (!FoundRTL) {
356	      ODBG(ODT_Deinit) << "No RTLs in use support the image "
357	                       << Img->ImageStart;
358	    }
359	  }
360	  PM->RTLsMtx.unlock();
361	  ODBG(ODT_Deinit) << "Done unregistering images!";
362	
363	  // Remove entries from PM->HostPtrToTableMap
364	  PM->TblMapMtx.lock();
365	  for (llvm::offloading::EntryTy *Cur = Desc->HostEntriesBegin;
366	       Cur < Desc->HostEntriesEnd; ++Cur) {
367	    if (Cur->Kind == object::OffloadKind::OFK_OpenMP)
368	      PM->HostPtrToTableMap.erase(Cur->Address);
369	  }
370	
371	  // Remove translation table for this descriptor.
372	  auto TransTable =
373	      PM->HostEntriesBeginToTransTable.find(Desc->HostEntriesBegin);
374	  if (TransTable != PM->HostEntriesBeginToTransTable.end()) {
375	    ODBG(ODT_Deinit) << "Removing translation table for descriptor "
376	                     << Desc->HostEntriesBegin;
377	    PM->HostEntriesBeginToTransTable.erase(TransTable);
378	  } else {
379	    ODBG(ODT_Deinit) << "Translation table for descriptor "
380	                     << Desc->HostEntriesBegin << " cannot be found, probably "
381	                     << "it has been already removed.";
382	  }
383	
384	  PM->TblMapMtx.unlock();
385	
386	  ODBG(ODT_Deinit) << "Done unregistering library!";
387	}
388	
389	/// Map global data and execute pending ctors
390	static int loadImagesOntoDevice(DeviceTy &Device) {
391	  /*
392	   * Map global data
393	   */
394	  int32_t DeviceId = Device.DeviceID;
395	  int Rc = OFFLOAD_SUCCESS;
396	  {
397	    std::lock_guard<decltype(PM->TrlTblMtx)> LG(PM->TrlTblMtx);
398	    for (auto *HostEntriesBegin : PM->HostEntriesBeginRegistrationOrder) {
399	      TranslationTable *TransTable =
400	          &PM->HostEntriesBeginToTransTable[HostEntriesBegin];
401	      ODBG(ODT_Init) << "Trans table " << TransTable->HostTable.EntriesBegin
402	                     << " : " << TransTable->HostTable.EntriesEnd;
403	      if (TransTable->HostTable.EntriesBegin ==
404	          TransTable->HostTable.EntriesEnd) {
405	        // No host entry so no need to proceed
406	        continue;
407	      }
408	
409	      if (TransTable->TargetsTable[DeviceId] != 0) {
410	        // Library entries have already been processed
411	        continue;
412	      }
413	
414	      // 1) get image.
415	      assert(TransTable->TargetsImages.size() > (size_t)DeviceId &&
416	             "Not expecting a device ID outside the table's bounds!");
417	      __tgt_device_image *Img = TransTable->TargetsImages[DeviceId];
418	      if (!Img) {
419	        REPORT() << "No image loaded for device id " << DeviceId << ".";
420	        Rc = OFFLOAD_FAIL;
421	        break;
422	      }
423	
424	      // 2) Load the image onto the given device.
425	      auto BinaryOrErr = Device.loadBinary(Img);
426	      if (llvm::Error Err = BinaryOrErr.takeError()) {
427	        REPORT() << "Failed to load image " << llvm::toString(std::move(Err));
428	        Rc = OFFLOAD_FAIL;
429	        break;
430	      }
431	
432	      // 3) Create the translation table.
433	      llvm::SmallVector<llvm::offloading::EntryTy> &DeviceEntries =
434	          TransTable->TargetsEntries[DeviceId];
435	      for (llvm::offloading::EntryTy &Entry :
436	           llvm::make_range(Img->EntriesBegin, Img->EntriesEnd)) {
437	        if (Entry.Kind != object::OffloadKind::OFK_OpenMP)
438	          continue;
439	
440	        __tgt_device_binary &Binary = *BinaryOrErr;
441	
442	        llvm::offloading::EntryTy DeviceEntry = Entry;
443	        if (Entry.Size) {
444	          if (!(Entry.Flags & OMP_DECLARE_TARGET_INDIRECT_VTABLE))
445	            if (Device.RTL->get_global(Binary, Entry.Size, Entry.SymbolName,
446	                                       &DeviceEntry.Address) != OFFLOAD_SUCCESS)
447	              REPORT() << "Failed to load symbol " << Entry.SymbolName;
448	
449	          // If unified memory is active, the corresponding global is a device
450	          // reference to the host global. We need to initialize the pointer on
451	          // the device to point to the memory on the host.
452	          if (!(Entry.Flags & OMP_DECLARE_TARGET_INDIRECT_VTABLE) &&
453	              !(Entry.Flags & OMP_DECLARE_TARGET_INDIRECT) &&
454	              ((PM->getRequirements() & OMP_REQ_UNIFIED_SHARED_MEMORY) ||
455	               (PM->getRequirements() & OMPX_REQ_AUTO_ZERO_COPY)))
456	            if (Device.RTL->data_submit(DeviceId, DeviceEntry.Address,
457	                                        Entry.Address,
458	                                        Entry.Size) != OFFLOAD_SUCCESS)
459	              REPORT() << "Failed to write symbol for USM " << Entry.SymbolName;
460	        } else if (Entry.Address) {
461	          if (Device.RTL->get_function(Binary, Entry.SymbolName,
462	                                       &DeviceEntry.Address) != OFFLOAD_SUCCESS)
463	            REPORT() << "Failed to load kernel " << Entry.SymbolName;
464	        }
465	        ODBG(ODT_Mapping) << "Entry point " << Entry.Address << " maps to"
466	                          << (Entry.Size ? " global" : "") << " "
467	                          << Entry.SymbolName << " (" << DeviceEntry.Address
468	                          << ")";
469	
470	        DeviceEntries.emplace_back(DeviceEntry);
471	      }
472	
473	      // Set the storage for the table and get a pointer to it.
474	      __tgt_target_table DeviceTable{&DeviceEntries[0],
475	                                     &DeviceEntries[0] + DeviceEntries.size()};
476	      TransTable->DeviceTables[DeviceId] = DeviceTable;
477	      __tgt_target_table *TargetTable = TransTable->TargetsTable[DeviceId] =
478	          &TransTable->DeviceTables[DeviceId];
479	
480	      MappingInfoTy::HDTTMapAccessorTy HDTTMap =
481	          Device.getMappingInfo().HostDataToTargetMap.getExclusiveAccessor();
482	
483	      __tgt_target_table *HostTable = &TransTable->HostTable;
484	      for (llvm::offloading::EntryTy *
485	               CurrDeviceEntry = TargetTable->EntriesBegin,
486	              *CurrHostEntry = HostTable->EntriesBegin,
487	              *EntryDeviceEnd = TargetTable->EntriesEnd;
488	           CurrDeviceEntry != EntryDeviceEnd;
489	           CurrDeviceEntry++, CurrHostEntry++) {
490	        if (CurrDeviceEntry->Size == 0 ||
491	            CurrDeviceEntry->Kind != object::OffloadKind::OFK_OpenMP)
492	          continue;
493	
494	        assert(CurrDeviceEntry->Size == CurrHostEntry->Size &&
495	               "data size mismatch");
496	
497	        // Fortran may use multiple weak declarations for the same symbol,
498	        // therefore we must allow for multiple weak symbols to be loaded from
499	        // the fat binary. Treat these mappings as any other "regular"
500	        // mapping. Add entry to map.
501	        if (Device.getMappingInfo().getTgtPtrBegin(
502	                HDTTMap, CurrHostEntry->Address, CurrHostEntry->Size))
503	          continue;
504	
505	        void *CurrDeviceEntryAddr = CurrDeviceEntry->Address;
506	
507	        // For indirect mapping, follow the indirection and map the actual
508	        // target.
509	        if (CurrDeviceEntry->Flags & OMP_DECLARE_TARGET_INDIRECT) {
510	          AsyncInfoTy AsyncInfo(Device);
511	          void *DevPtr;
512	          Device.retrieveData(&DevPtr, CurrDeviceEntryAddr, sizeof(void *),
513	                              AsyncInfo, /*Entry=*/nullptr, &HDTTMap);
514	          if (AsyncInfo.synchronize() != OFFLOAD_SUCCESS)
515	            return OFFLOAD_FAIL;
516	          CurrDeviceEntryAddr = DevPtr;
517	        }
518	
519	        ODBG(ODT_Mapping) << "Add mapping from host " << CurrHostEntry->Address
520	                          << " to device " << CurrDeviceEntry->Address
521	                          << " with size " << CurrDeviceEntry->Size
522	                          << ", name \"" << CurrDeviceEntry->SymbolName << "\"";
523	        HDTTMap->emplace(new HostDataToTargetTy(
524	            (uintptr_t)CurrHostEntry->Address /*HstPtrBase*/,
525	            (uintptr_t)CurrHostEntry->Address /*HstPtrBegin*/,
526	            (uintptr_t)CurrHostEntry->Address +
527	                CurrHostEntry->Size /*HstPtrEnd*/,
528	            (uintptr_t)CurrDeviceEntryAddr /*TgtAllocBegin*/,
529	            (uintptr_t)CurrDeviceEntryAddr /*TgtPtrBegin*/,
530	            false /*UseHoldRefCount*/, CurrHostEntry->SymbolName,
531	            true /*IsRefCountINF*/));
532	
533	        // Notify about the new mapping.
534	        if (Device.notifyDataMapped(CurrHostEntry->Address,
535	                                    CurrHostEntry->Size))
536	          return OFFLOAD_FAIL;
537	      }
538	    }
539	    Device.setHasPendingImages(false);
540	  }
541	
542	  if (Rc != OFFLOAD_SUCCESS)
543	    return Rc;
544	
545	  static Int32Envar DumpOffloadEntries =
546	      Int32Envar("OMPTARGET_DUMP_OFFLOAD_ENTRIES", -1);
547	  if (DumpOffloadEntries.get() == DeviceId)
548	    Device.dumpOffloadEntries();
549	
550	  return OFFLOAD_SUCCESS;
551	}
552	
553	Expected<DeviceTy &> PluginManager::getDevice(uint32_t DeviceNo) {
554	  DeviceTy *DevicePtr;
555	  {
556	    auto ExclusiveDevicesAccessor = getExclusiveDevicesAccessor();
557	    if (DeviceNo >= ExclusiveDevicesAccessor->size())
558	      return error::createOffloadError(
559	          error::ErrorCode::INVALID_VALUE,
560	          "device number '%i' out of range, only %i devices available",
561	          DeviceNo, ExclusiveDevicesAccessor->size());
562	
563	    DevicePtr = &*(*ExclusiveDevicesAccessor)[DeviceNo];
564	  }
565	
566	  // Check whether global data has been mapped for this device
567	  if (DevicePtr->hasPendingImages())
568	    if (loadImagesOntoDevice(*DevicePtr) != OFFLOAD_SUCCESS)
569	      return error::createOffloadError(error::ErrorCode::BACKEND_FAILURE,
570	                                       "failed to load images on device '%i'",
571	                                       DeviceNo);
572	  return *DevicePtr;
573	}
